  min-height: 44px;
  min-width: 44px;
  width: 100%;
  font: inherit;
  font-weight: 600;
  color: #fff;
  background: #3b46d6;
  border: 0;
  border-radius: 0.5rem;
  padding: 0.5rem 1rem;
  cursor: pointer;
}
button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
textarea {
  width: 100%;
  min-height: 6rem;
  font: inherit;
  padding: 0.5rem;
  border: 2px solid #cfd3e2;
  border-radius: 0.5rem;
}
:focus-visible {
  outline: 3px solid #ff9f1c;
  outline-offset: 2px;
}
.comment-section {
  margin-top: 1rem;
}
.comment-label {
  display: block;
  font-weight: 600;
  font-size: 0.95rem;
  margin-bottom: 0.25rem;
}
.comment-disclosure {
  font-size: 0.825rem;
  color: #52525b;
  line-height: 1.4;
  margin: 0 0 0.5rem;
}
.lead-preview {
  font-size: 0.9rem;
  color: #27272a;
  margin-top: 0.5rem;
