  border-bottom: none;
}
ul.actions {
  list-style: none;
  padding: 0;
  margin: 1rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
ul.actions li {
  min-height: 44px;
  padding: 0.6rem 0.75rem;
  background: #fff;
  border: 2px solid #cfd3e2;
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
}
.err {
  color: #b00020;
  background: #fde8e8;
  padding: 0.75rem;
  border-radius: 0.5rem;
  margin-bottom: 1rem;
}
.state-box {
  background: #fff;
  border: 2px solid #cfd3e2;
  border-radius: 0.5rem;
  padding: 1.5rem;
  margin: 1rem 0;
  text-align: center;
}
@media (min-width: 640px) {
  body.is-desktop .mobile-next-btn {
    display: none !important;
  }
  body.is-desktop .desktop-finish-btn {
    display: block !important;
    margin-top: 1.5rem;
  }
